        powerAgeMs: telemetry.powerAgeMs ?? null, powerUpdatedMs: telemetry.powerUpdatedMs ?? null,
        chargingCutoff, dischargingCutoff, atChargingCutoff, atDischargingCutoff,
        rs485Entity, rs485State, rs485Enabled, telemetryUsable,
        boundaryIdle: telemetry.boundaryIdle === true,
        activePower: telemetry.activePower === true,
        heartbeatAgeMs: telemetry.heartbeatAgeMs ?? null,
        freshnessMode: telemetry.freshnessMode || 'unknown',
        powerFreshnessLimitMs: telemetry.powerFreshnessLimitMs ?? null,
        charging: false, status: stale ? 'uncertain' : 'unavailable', maxChargeKnown,
        maxChargePower: maxChargeKnown ? maxChargePower : 0, maxChargeSource, maxChargeAgeMs,
        rawHeadroom: 0, effectiveChargeCeiling: 0, learnedTaperCeiling: null,
        normalHeadroom: 0, taperConfirmedHeadroom: 0, taperReleaseAllowance: 0, taperStepCap: 0,
        taperBand: null, taperStableSeconds: 0, taperProbeEligible: false, taperAwaitingConfirmation: false,
        taperFailureCount: 0, taperProbeBlockedSeconds: 0, taperRecoveryRequired: false,
