const activitySummaryHtml = `<div class="activity-summary"><div><span>Charge Priority</span><strong>${esc(`${act.chargeSessions || 0} sessions · ${act.chargeDuration || '0 min'} · ${act.chargeIncreases || 0} increases`)}</strong></div><div><span>PV limiting</span><strong>${esc(`${act.limitSessions || 0} sessions · ${act.limitDuration || '0 min'} · ${act.reductions || 0} reductions`)}</strong></div><div><span>PV restore</span><strong>${esc(`${act.restoreActions || 0} actions`)}</strong></div><div><span>Faults/control pauses</span><strong>${esc(act.faults || 0)}</strong></div><div><span>Available coverage</span><strong>${esc(act.coverageText || 'No activity rows')}</strong></div><div><span>History status</span><strong>${esc(act.historyNote || 'Unknown')}</strong></div></div>`;
const activityMetricsHtml = `<div class="compact-grid"><div><small>PV constrained</small><b>${esc(kwhText(act.constrainedKwh))}</b></div><div><small>Battery charged</small><b>${esc(kwhText(act.batteryChargeKwh))}</b></div><div><small>Activity samples in deadband</small><b>${finite(act.activitySamplesWithinDeadbandPercent) ? `${Math.round(act.activitySamplesWithinDeadbandPercent)}%` : '—'}</b></div><div><small>Peak battery charge</small><b>${esc(watts(act.peakBatteryChargeW))}</b></div><div><small>Largest reduction</small><b>${esc(watts(act.maxReductionW))}</b></div><div><small>Largest restore</small><b>${esc(watts(act.maxRestoreW))}</b></div></div>`;
const accuracyHasData = finite(report.accuracy.value);
const accuracyValue = accuracyHasData ? `${Math.round(report.accuracy.value)}%` : 'No data collected today';
const runtimeWarning = report.runtimeDiagnostics?.warning ? `<div class="runtime-warning"><strong>Runtime data notice</strong><span>${esc(report.runtimeDiagnostics.warning)}</span></div>` : '';

msg.hpvcHtmlParts = {
    settings,
    inv,
    d,
    s,
    inverterCards,
    batteryCards,
    healthRows,
    displayInsights,
    insightRows,
    insightSummary,
    activity,
    act,
    activityRows,
    activitySummaryHtml,
    activityMetricsHtml,
    accuracyHasData,
    accuracyValue,
    runtimeWarning
};
return msg;

// Verify renderer manifests and the actual visible common values in both formats.
const report = msg.hpvcReport;
const html = String(msg.hpvcHtmlReport || msg.payload || '');
const text = String(msg.hpvcTxtReport || '');
const expectedManifest = JSON.stringify(report && report.parityManifest ? report.parityManifest : {});
const txtManifest = String(msg.hpvcTxtParityManifest || '');
const htmlManifest = String(msg.hpvcHtmlParityManifest || '');
const errors = [];

function finite(value) {
    return value !== null && value !== undefined && Number.isFinite(Number(value));
}
function watts(value, decimals = 0) {
    return finite(value) ? `${Number(value).toFixed(decimals)} W` : 'unavailable';
}

function price(value) { return finite(value) ? `${Number(value).toFixed(4)} €/kWh` : 'unavailable'; }
function pct(value) { return finite(value) ? `${Math.round(Number(value))}%` : 'No data collected today'; }
function age(value) { return finite(value) ? `${Math.round(Number(value))} s` : '—'; }
function esc(value) { return String(value ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;'); }
function txt(token, label) { if (!text.includes(token)) errors.push(`TXT mismatch: ${label}`); }
function htm(token, label) { if (!visibleHtml.includes(token)) errors.push(`HTML mismatch: ${label}`); }
function htmlRow(label, value) { return `<span>${esc(label)}</span><strong>${esc(value)}</strong>`; }
function htmlCard(label, value) { return `<small>${esc(label)}</small><b>${esc(value)}</b>`; }
function ordered(haystack, tokens, label) { let pos=-1; for (const token of tokens) { const next=haystack.indexOf(token,pos+1); if (next<0) { errors.push(`${label}: missing ${token}`); return; } if (next<pos) { errors.push(`${label}: wrong order at ${token}`); return; } pos=next; } }

// Exclude the hidden downloadable TXT and scripts so they cannot satisfy HTML checks.
const visibleHtml = html
    .replace(/<pre\s+id="raw"[\s\S]*?<\/pre>/i, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '');

if (!report || typeof report !== 'object') errors.push('shared report model missing');
if (!expectedManifest || expectedManifest === '{}') errors.push('parity manifest missing');
if (txtManifest !== expectedManifest) errors.push('TXT renderer manifest differs from shared model');
if (htmlManifest !== expectedManifest) errors.push('HTML renderer manifest differs from shared model');

for (const section of [
    'Executive Summary', 'Live Status', 'Decision Evaluation', 'Today’s Accuracy',
    'Inverters', 'Control Settings', 'HBC & Battery Status', 'Sensor Health', 'Today’s Insights'
]) {
    if (!visibleHtml.includes(`>${section}<`) && !visibleHtml.includes(`>${esc(section)}<`)) {
        errors.push(`HTML mismatch: section ${section}`);
    }
}
for (const section of [
    'EXECUTIVE SUMMARY', 'LIVE STATUS', 'DECISION EVALUATION', "TODAY'S ACCURACY",
    'INVERTERS', 'CONTROL SETTINGS', 'HBC & BATTERY STATUS', 'Sensor Health', 'TODAY’S INSIGHTS'
]) {
    txt(`[${section}]`, `section ${section}`);
}

if (report && typeof report === 'object') {
    const s = report.summary || {};
    const d = report.decision || {};
    const a = report.accuracy || {};
    const settings = report.settings || {};
    const inv = report.inverterSummary || {};

    txt(`Generated: ${report.generated}`, 'generation timestamp');
    txt(`Version: ${report.version}`, 'version');
    htm(`${esc(report.generated)} · v${esc(report.version)}`, 'generation metadata');

    const summaryFields = [
        ['HPVC status', s.enabled ? 'Enabled' : 'Disabled'],
        ['Configuration', s.configValid ? 'Valid' : 'Invalid'],
        ['Control mode', s.controlMode],
        ['Current decision', s.status],
        ['Reason', s.reason],
        ['Current action', s.currentAction],
        ['Action result', s.actionResult],
        ['HBC control', s.hbcControl ? 'On' : 'Off'],
        ['HBC strategy', s.hbcStrategy],
        ['Runtime evaluation', s.runtimeEvaluationTime]
    ];
    for (const [label, value] of summaryFields) {
        txt(`${label}: ${value}`, label);
        htm(htmlRow(label, value), label);
    }
    if (s.runtimeDiagnosticsWarning) { txt(`Runtime data warning: ${s.runtimeDiagnosticsWarning}`, 'Runtime data warning'); htm(htmlRow('Runtime data warning', s.runtimeDiagnosticsWarning), 'Runtime data warning'); }

    const gridHtml = finite(report.live?.grid)
        ? `${Math.abs(Math.round(Number(report.live.grid)))} W ${Number(report.live.grid) < 0 ? 'export' : 'import'}`
        : 'unavailable';
    txt(`Grid power: ${watts(report.live?.grid)} (Target ${watts(settings.targetExport)})`, 'grid power');
    htm(htmlCard('GRID', gridHtml), 'grid power');
    txt(`PV production: ${watts(report.live?.pv, 1)} (Current solar power)`, 'PV production');
    htm(htmlCard('PV', watts(report.live?.pv, 1)), 'PV production');
    txt(`Market/export price: ${price(report.live?.market)} (PV control price)`, 'market/export price');
    htm(htmlCard('MARKET/EXPORT PRICE', price(report.live?.market)), 'market/export price');
    txt(`All-in price: ${price(report.live?.allIn)} (Negative-price control)`, 'all-in price');
    htm(htmlCard('ALL-IN PRICE', price(report.live?.allIn)), 'all-in price');

    const decisionFields = [
        ['Export limiting condition', d.exportTriggered ? 'Triggered' : 'Not triggered'],
        ['Import restore condition', d.importTriggered ? 'Triggered' : 'Not triggered'],
        ['PV currently limited', d.pvLimited ? 'Yes' : 'No'],
        ['Negative-price mode', d.negativeMode ? 'Active' : 'Inactive'],
        ['Cooldown', d.cooldown ? 'Active' : 'Inactive'],
        ['Deadband', d.deadbandInside ? 'Inside' : 'Outside'],
        ['Minimum PV block', d.minimumPvBlock ? 'Active' : 'Inactive'],
        ['Grid error to target', watts(d.gridError)],
        ['HBC Charge Priority', d.chargePriorityState || (d.chargePriorityActive ? 'Active' : 'Off')],
        ['PV increase possible', report.hbc?.increasePossible ? 'Yes' : 'No'],
        ['Charge Priority reason', report.hbc?.stateReason],
        ['Taper probe', d.taperProbeActive ? 'Active' : 'Inactive'],
        ['Decision snapshot', d.runtimeEvaluationTime],
        ['Decision snapshot age', age(d.runtimeDiagnosticsAgeSeconds)]
    ];
    for (const [label, value] of decisionFields) {
        txt(`${label}: ${value}`, label);
        htm(htmlRow(label, value), label);
    }
    if (d.runtimeDiagnosticsWarning) { txt(`Decision data warning: ${d.runtimeDiagnosticsWarning}`, 'Decision data warning'); htm(htmlRow('Decision data warning', d.runtimeDiagnosticsWarning), 'Decision data warning'); }

    txt(`Daily Target Accuracy: ${pct(a.value)}`, 'daily target accuracy');
    htm(`<div class="accuracy-score${finite(a.value) ? '' : ' no-data'}">${esc(pct(a.value))}</div>`, 'daily target accuracy');
    for (const [label, value] of [
        ['Rating', a.rating],
        ['Control response', `${Number(a.factors?.control || 0).toFixed(1)}%`],
        ['House load changes', `${Number(a.factors?.load || 0).toFixed(1)}%`],
        ['PV availability', `${Number(a.factors?.pv || 0).toFixed(1)}%`],
        ['Other', `${Number(a.factors?.other || 0).toFixed(1)}%`]
    ]) {
        txt(`${label === 'Rating' ? 'Target rating' : label}: ${value}`, label);
        if (label === 'Rating') htm(`<span class="rating-pill">${esc(value)}</span>`, label);
        else htm(htmlRow(label, value), label);
    }

    for (const inverter of report.inverters || []) {
        const requested = finite(inverter.requestedTarget) ? watts(inverter.requestedTarget) : '—';
        const txtLine = `- ${inverter.name}: current=${watts(inverter.current)}, maximum=${watts(inverter.maximum)}, minimum=${watts(inverter.minimum)}, calculated target=${watts(inverter.calculatedTarget)}, requested target=${requested}, difference=${watts(inverter.difference)}, at min/max=${inverter.atBoundary ? 'Yes' : 'No'}, write required=${inverter.writeRequired ? 'Yes' : 'No'}, last verification=${inverter.verification}`;
        txt(txtLine, `inverter ${inverter.name}`);
        htm(`<h3>${esc(inverter.name)}</h3>`, `inverter ${inverter.name}`);
        for (const [label, value] of [
            ['Current limit', watts(inverter.current)], ['Maximum power', watts(inverter.maximum)],
            ['Minimum power', watts(inverter.minimum)], ['Calculated target', watts(inverter.calculatedTarget)],
            ['Requested target', requested], ['Difference from target', watts(inverter.difference)],
            ['At minimum or maximum', inverter.atBoundary ? 'Yes' : 'No'], ['Write required', inverter.writeRequired ? 'Yes' : 'No'],
            ['Last verification', inverter.verification]
        ]) htm(htmlRow(label, value), `inverter ${inverter.name} ${label}`);
    }

    for (const [label, value] of [
        ['Configured inverters', inv.configuredCount],
        ['Available inverters', inv.availableCount],
        ['Unavailable inverters', Math.max(0, Number(inv.configuredCount || 0) - Number(inv.availableCount || 0))],
        ['Current total limit', watts(inv.currentTotal)],
        ['Minimum total limit', watts(inv.minimumTotal)],
        ['Maximum total power', watts(inv.maximumTotal)],
        ['Calculated total target', watts(inv.targetTotal)],
        ['Difference to target', watts(Number(inv.targetTotal || 0) - Number(inv.currentTotal || 0))],
        ['Available increase', watts(Math.max(0, Number(inv.maximumTotal || 0) - Number(inv.currentTotal || 0)))],
        ['Available reduction', watts(Math.max(0, Number(inv.currentTotal || 0) - Number(inv.minimumTotal || 0)))],
        ['Pending writes', inv.requestedCount],
        ['Write verification', inv.verificationStatus],
        ['Last write reason', inv.lastWriteReason],
        ['Last write time', inv.lastWriteTime],
        ['Last verification', inv.lastVerificationTime],
        ['Diagnostics timestamp', inv.diagnosticsTime],
        ['Diagnostics age', age(inv.diagnosticsAgeSeconds)],
        ['Data source', inv.dataSource],
        ['Control mode', s.controlMode]
    ]) { txt(`${label}: ${value}`, label); htm(htmlRow(label, value), label); }

    const settingFields = [
        ['PV limit price', price(settings.limitPrice)],
        ['Price hysteresis', price(settings.priceHysteresis)],
        ['Export Start', watts(settings.exportStart, 1)],
        ['Target Export', watts(settings.targetExport, 1)],
        ['Import Restore', watts(settings.importRestore, 1)],
        ['Minimum PV', watts(settings.minimumPv, 1)],
        ['Night restore PV', watts(settings.nightRestorePv, 1)],
        ['Cooldown', finite(settings.cooldownSeconds) ? `${Number(settings.cooldownSeconds).toFixed(1)} s` : 'unavailable'],
        ['Deadband', watts(settings.deadband, 1)]
    ];
    for (const [label, value] of settingFields) {
        txt(`${label}: ${value}`, label);
        htm(htmlRow(label, value), label);
    }

    const overrideDrift = Array.isArray(report.hbc?.negativeOverrideInverterDrift)
        ? report.hbc.negativeOverrideInverterDrift
        : [];
    const negativeOverrideFields = [
        ['Override state', report.hbc?.negativeOverrideState],
        ['Minimum-PV lock', report.hbc?.negativeOverrideLockActive ? 'Active' : 'Inactive'],
        ['Override reason', report.hbc?.negativeOverrideReason],
        ['Saved HBC strategy', report.hbc?.negativeOverrideSavedStrategy || '—'],
        ['Saved charge goal', report.hbc?.negativeOverrideSavedChargeGoal || '—'],
        ['Last override call', report.hbc?.negativeOverrideLastCallStep || '—'],
        ['Override phase age', age(report.hbc?.negativeOverridePhaseAgeSeconds)],
        ['Override retries', report.hbc?.negativeOverrideRetryCount],
        ['Override fault', report.hbc?.negativeOverrideFaultActive ? 'Active' : 'Inactive'],
        ['Override persistence ready', report.hbc?.negativeOverridePersistenceReady ? 'Yes' : 'No'],
        ['Inverter minimum drift', report.hbc?.negativeOverrideState === 'inactive' ? 'Not applicable' : (overrideDrift.length ? overrideDrift.join(', ') : 'None')]
    ];
    for (const [label, value] of negativeOverrideFields) {
        txt(`${label}: ${value}`, label);
        htm(htmlRow(label, value), label);
    }

    const hbcFields = [
        ['HBC status', report.hbc?.available ? 'Detected' : 'Not detected'],
        ['HBC control', report.hbc?.control ? 'On' : 'Off'],
        ['HBC Charge Priority', report.hbc?.chargePriorityState || (report.hbc?.chargePriorityActive ? 'Active' : 'Off')],
        ['HBC strategy', report.hbc?.strategy],
        ['Executing substrategy', report.hbc?.executing],
        ['HBC charge goal', report.hbc?.chargeGoal],
        ['State reason', report.hbc?.stateReason],
        ['PV increase possible', report.hbc?.increasePossible ? 'Yes' : 'No'],
        ['Eligible batteries', `${report.hbc?.eligibleBatteryCount} (${report.hbc?.below90EligibleCount} normal, ${report.hbc?.taperEligibleCount} taper-aware)`],
        ['Usable batteries', report.hbc?.usableCount],
        ['Uncertain batteries excluded', report.hbc?.uncertainExcluded],
        ['Unavailable batteries excluded', report.hbc?.unavailableExcluded],
        ['RS485-disabled batteries excluded', report.hbc?.controlDisabledExcluded || 0],
        ['Combined battery headroom', watts(report.hbc?.combinedBatteryHeadroom)],
        ['Normal battery headroom', watts(report.hbc?.normalBatteryHeadroom)],
        ['Controlled taper allowance', watts(report.hbc?.taperBatteryAllowance)],
        ['Existing grid export', watts(report.hbc?.existingGridExport)],
        ['Net absorbable headroom', watts(report.hbc?.netAbsorbableHeadroom)],
        ['Remaining inverter capacity', watts(report.hbc?.remainingInverterCapacity)],
        ['Charge Priority step cap', watts(report.hbc?.stepCap)],
        ['Calculated PV increase', watts(report.hbc?.calculatedIncrease)],
        ['Charge Priority target', watts(report.hbc?.targetTotal)],
        ['Taper probe', report.hbc?.taperProbeActive ? 'Active' : 'Inactive'],
        ['Charge Priority diagnostics', report.hbc?.diagnosticsEvaluationTime],
        ['Charge Priority internal state', report.hbc?.stateMachineState || 'off'],
        ['HBC prioritized battery', report.hbc?.prioritizedBattery ? `M${report.hbc.prioritizedBattery}` : '—'],
        ['HBC battery order', Array.isArray(report.hbc?.batteryOrder) && report.hbc.batteryOrder.length ? report.hbc.batteryOrder.map(i => `M${i}`).join(' → ') : '—'],
        ['HBC priority cycle', report.hbc?.priorityCycleMode || 'Unknown'],
        ['HBC priority configuration', report.hbc?.priorityConfigurationValid ? 'Valid' : `Invalid${report.hbc?.priorityConfigurationReason ? ` — ${report.hbc.priorityConfigurationReason}` : ''}`],
        ['Confirmed-charge enter threshold', watts(report.hbc?.confirmedChargeEnterThreshold)],
        ['Confirmed-charge remain threshold', watts(report.hbc?.confirmedChargeRemainThreshold)],
        ['Measured battery charge power', watts(report.hbc?.batteryChargePower)],
        ['Battery charging confirmed', report.hbc?.batteryChargingConfirmed ? 'Yes' : 'No'],
        ['HBC response window', report.hbc?.responseWindowActive ? 'Active' : 'Inactive'],
        ['HBC response window duration', finite(report.hbc?.responseWindowMs) ? `${Math.round(report.hbc.responseWindowMs / 1000)} s` : 'unavailable'],
        ['HBC response window remaining', finite(report.hbc?.responseWindowRemainingMs) ? `${Math.ceil(report.hbc.responseWindowRemainingMs / 1000)} s` : 'unavailable'],
        ['Charge Priority exit hold', report.hbc?.exitHoldActive ? 'Active' : 'Inactive'],
        ['Charge Priority exit hold duration', finite(report.hbc?.exitHoldMs) ? `${Math.round(report.hbc.exitHoldMs / 1000)} s` : 'unavailable'],
        ['Charge Priority exit hold remaining', finite(report.hbc?.exitHoldRemainingMs) ? `${Math.ceil(report.hbc.exitHoldRemainingMs / 1000)} s` : 'unavailable'],
        ['Persistent export age', finite(report.hbc?.persistentExportAgeMs) ? `${Math.round(report.hbc.persistentExportAgeMs / 1000)} s` : 'unavailable'],
        ['Export fallback threshold', finite(report.hbc?.exportFallbackMs) ? `${Math.round(report.hbc.exportFallbackMs / 1000)} s` : 'unavailable'],
        ['Export fallback', report.hbc?.exportFallbackActive ? 'Active' : 'Inactive'],
        ['HPVC export limiting suppressed', report.hbc?.exportLimitingSuppressed ? 'Yes' : 'No'],
        ['Battery diagnostics timestamp', report.hbc?.diagnosticsTime],
        ['Battery diagnostics age', age(report.hbc?.diagnosticsAgeSeconds)]
    ];
    for (const [label, value] of hbcFields) {
        txt(`${label}: ${value}`, label);
        htm(htmlRow(label, value), label);
    }

    for (const battery of report.batteries || []) {
        const soc = finite(battery.soc) ? `${battery.soc}%` : 'unavailable';
        const txtLine = `- ${battery.name}: status=${battery.status}, SOC=${soc}, actual power=${watts(battery.power)}, max charge power=${watts(battery.maxChargePower)}, RS485=${battery.rs485Enabled ? 'enable' : (battery.rs485State || 'unknown')}, effective ceiling=${watts(battery.effectiveChargeCeiling)}, learned taper ceiling=${finite(battery.learnedTaperCeiling) ? watts(battery.learnedTaperCeiling) : '—'}, taper band=${battery.taperBand || '—'}, stable charging=${finite(battery.taperStableSeconds) ? `${Math.round(battery.taperStableSeconds)} s` : '—'}, probe eligible=${battery.taperProbeEligible ? 'Yes' : 'No'}, awaiting taper confirmation=${battery.taperAwaitingConfirmation ? 'Yes' : 'No'}, per-battery taper step cap=${watts(battery.taperStepCap)}, confirmed taper headroom=${watts(battery.taperConfirmedHeadroom)}, controlled taper allowance=${watts(battery.taperReleaseAllowance)}, charger eligible=${battery.priorityEligible ? 'Yes' : 'No'}, SOC mode=${battery.socMode}, headroom contribution=${watts(battery.headroomContribution)}, headroom=${watts(battery.headroom)}, telemetry=${battery.telemetry}, freshness mode=${battery.freshnessMode}, heartbeat age=${age(battery.heartbeatAgeSeconds)}, power age=${age(battery.powerAgeSeconds)}, SOC age=${age(battery.socAgeSeconds)}, reason=${battery.reason}`;
        txt(txtLine, `battery ${battery.name}`);
        htm(`<h3>${esc(battery.name)}</h3>`, `battery ${battery.name}`);
        for (const [label, value] of [
            ['Status', battery.status], ['SOC', soc], ['Actual power', watts(battery.power)],
            ['Maximum charge power', watts(battery.maxChargePower)], ['RS485 control', battery.rs485Enabled ? 'enable' : (battery.rs485State || 'unknown')], ['Effective charge ceiling', watts(battery.effectiveChargeCeiling)],
            ['Learned taper ceiling', finite(battery.learnedTaperCeiling) ? watts(battery.learnedTaperCeiling) : '—'],
            ['Taper SOC band', battery.taperBand || '—'],
            ['Stable charging time', finite(battery.taperStableSeconds) ? `${Math.round(battery.taperStableSeconds)} s` : '—'],
            ['Probe eligible', battery.taperProbeEligible ? 'Yes' : 'No'],
            ['Awaiting taper confirmation', battery.taperAwaitingConfirmation ? 'Yes' : 'No'],
            ['Per-battery taper step cap', watts(battery.taperStepCap)],
            ['Confirmed taper headroom', watts(battery.taperConfirmedHeadroom)],
            ['Controlled taper allowance', watts(battery.taperReleaseAllowance)],
            ['Eligible for Charge Priority', battery.priorityEligible ? 'Yes' : 'No'],
            ['SOC mode', battery.socMode],
            ['Headroom contribution', watts(battery.headroomContribution)],
            ['Charging headroom', watts(battery.headroom)], ['Telemetry', battery.telemetry], ['Freshness mode', battery.freshnessMode],
            ['Heartbeat age', age(battery.heartbeatAgeSeconds)], ['Power age', age(battery.powerAgeSeconds)],
            ['SOC age', age(battery.socAgeSeconds)], ['Reason', battery.reason]
        ]) htm(htmlRow(label, value), `battery ${battery.name} ${label}`);
    }

    for (const sensor of report.sensorHealth || []) {
        const health = `${sensor.status} (${age(sensor.ageSeconds)})`;
        txt(`${sensor.label}: ${health} · ${sensor.entity}`, `sensor ${sensor.label}`);
        htm(`<span>${esc(sensor.label)}</span><strong>${esc(health)}</strong><code>${esc(sensor.entity)}</code>`, `sensor ${sensor.label}`);
    }

    txt(`Insight history source: ${report.insightHistorySource || 'latest-20 fallback'}`, 'Insight history source');
    htm(htmlRow('Insight history source', report.insightHistorySource || 'latest-20 fallback'), 'Insight history source');

    // HTML and TXT both use the same consecutive-grouped Insight model.
    const groupedInsights = Array.isArray(report.groupedInsights) ? report.groupedInsights : (report.insights || []);
    const insightSummary = report.insightSummary || { total: 0, grouped: 0, critical: 0, warnings: 0, information: 0 };
    txt(`Events: ${insightSummary.total} · Consecutive entries: ${insightSummary.grouped} · Critical: ${insightSummary.critical} · Warnings: ${insightSummary.warnings} · Info: ${insightSummary.information}`, 'Insight severity summary');
    for (const insight of groupedInsights) {
        const count = Math.max(1, Number(insight.count || 1));
        const timeLabel = count > 1 ? `${insight.time}–${insight.lastTime}` : insight.time;
        const severity = String(insight.severity || 'info').toUpperCase();
        txt(`${timeLabel} | ${severity} | ${insight.flow} | ${insight.node} | ${count} | ${insight.explanation}`, `insight ${timeLabel}`);
        htm(esc(timeLabel), `insight ${timeLabel} time`);
        htm(esc(insight.flow), `insight ${timeLabel} flow`);
        htm(esc(insight.node), `insight ${timeLabel} node`);
        htm(esc(insight.explanation), `insight ${timeLabel} explanation`);
        if (count > 1) htm(`×${count}`, `insight ${timeLabel} occurrence count`);
    }
}

ordered(visibleHtml, ['<section id="inverters">','<h3>','Inverter Diagnostics'], 'HTML inverter display order');
ordered(text, ['[INVERTERS]','[INVERTER DIAGNOSTICS]'], 'TXT inverter display order');
ordered(visibleHtml, ['Current HBC State','Negative All-In Override','Charge Priority Capacity','Batteries','HBC & Battery Diagnostics'], 'HTML HBC display order');
ordered(text, ['[CURRENT HBC STATE]','[NEGATIVE ALL-IN OVERRIDE]','[CHARGE PRIORITY CAPACITY]','[BATTERIES]','[HBC & BATTERY DIAGNOSTICS]'], 'TXT HBC display order');

msg.hpvcReportParity = {
    ok: errors.length === 0,
    errors,
    version: report && report.version,
    generated: report && report.generated,
    manifestBytes: expectedManifest.length,
    checkedVisibleValues: true
};
if (errors.length > 0) throw new Error(`HPVC report parity failed: ${errors.join('; ')}`);
msg.payload = html;
return msg;

function appendReportInsight(nodeName, message) {
    const now = Date.now();
    const d = new Date(now);
    const dateKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
