<section id="activity"><h2>Power Control — PV-limiting price zone</h2><p class="activity-note">Only activity from entry into the Market/export-price PV-limiting zone until exit above the configured restore threshold is shown. Activity outside that price window is intentionally omitted.</p>${activitySummaryHtml}${activityMetricsHtml}<details class="compact activity-table"><summary><span>Activity log · ${esc(act.rowCount || 0)} rows</span><span class="summary-badges">Show details</span></summary><div class="details-body"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Mode</th><th>Grid</th><th>PV</th><th>Battery</th><th>Limit</th><th>Event</th></tr></thead><tbody>${activityRows}</tbody></table></div></div></details><p class="activity-note">Constrained-capacity and battery-energy values are estimates from sparse active-control intervals. Restore energy is intentionally not estimated because stepped restores cannot be reconstructed reliably from activity events.</p></section><div class="floating-actions" aria-label="Report navigation"><button id="collapse-floating" class="floating-button hidden" type="button" aria-label="Collapse expanded Insights and Power Control sections">▲ Collapse</button><button id="top-floating" class="floating-button hidden" type="button" aria-label="Return to top of report">↑ Top</button></div><pre id="raw" class="hidden">${esc(msg.hpvcTxtReport)}</pre></main><script>(async()=>{try{const current=document.querySelector('meta[name="hpvc-generated"]')?.content||'';const response=await fetch(location.pathname+'?fresh='+Date.now(),{cache:'no-store',headers:{'Cache-Control':'no-cache'}});if(response.ok){const fresh=await response.text();const match=fresh.match(/<meta name="hpvc-generated" content="([^"]+)"/);if(match&&match[1]&&match[1]!==current){document.open();document.write(fresh);document.close();return;}}}catch(_){}})();document.getElementById('download').onclick=()=>{const b=new Blob([document.getElementById('raw').textContent],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='hpvc-report-${esc(report.generatedIso.replace(/[:.]/g,'-'))}.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};const expandableSections=[...document.querySelectorAll('details.compact')];const collapseButton=document.getElementById('collapse-floating');const topButton=document.getElementById('top-floating');function currentScrollTop(){return Math.max(window.scrollY||0,document.documentElement?.scrollTop||0,document.body?.scrollTop||0,document.scrollingElement?.scrollTop||0)}function updateFloatingButtons(){const hasOpenSection=expandableSections.some(section=>section.open);collapseButton?.classList.toggle('hidden',!hasOpenSection);topButton?.classList.toggle('hidden',currentScrollTop()<400)}function syncFloatingButtons(){requestAnimationFrame(()=>requestAnimationFrame(updateFloatingButtons))}expandableSections.forEach(section=>section.addEventListener('toggle',updateFloatingButtons));window.addEventListener('scroll',updateFloatingButtons,{passive:true});window.addEventListener('load',syncFloatingButtons,{once:true});window.addEventListener('pageshow',syncFloatingButtons);window.addEventListener('resize',syncFloatingButtons,{passive:true});window.addEventListener('orientationchange',syncFloatingButtons,{passive:true});document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncFloatingButtons()});window.visualViewport?.addEventListener('resize',syncFloatingButtons,{passive:true});window.visualViewport?.addEventListener('scroll',syncFloatingButtons,{passive:true});setTimeout(updateFloatingButtons,100);setTimeout(updateFloatingButtons,500);setTimeout(updateFloatingButtons,1200);let __navUntil=performance.now()+3000;function __watchNav(){updateFloatingButtons();if(performance.now()<__navUntil)requestAnimationFrame(__watchNav)}requestAnimationFrame(__watchNav);collapseButton?.addEventListener('click',()=>{const firstOpen=expandableSections.find(section=>section.open);expandableSections.forEach(section=>{section.open=false});firstOpen?.scrollIntoView({behavior:'smooth',block:'start'});updateFloatingButtons()});topButton?.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));updateFloatingButtons();fetch('/api/webhook/hpvc_report_viewed_140',{method:'POST',keepalive:true}).catch(()=>{});</script></body></html>`;
